// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32 constant PROPOSER = keccak256("PROPOSER_ROLE");
    bytes32 constant EXECUTOR = keccak256("EXECUTOR_ROLE");
    bytes32 constant ADMIN = keccak256("TIMELOCK_ADMIN_ROLE");

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 roleSel, address victim, address attacker) public {
        vm.assume(victim != address(0));
        vm.assume(attacker != victim);
        bytes32 role = roleSel % 3 == 0 ? PROPOSER : (roleSel % 3 == 1 ? EXECUTOR : ADMIN);

        // grant the fuzzed role to the victim using the deployer (default admin)
        vm.startPrank(address(this));
        c.grantRole(role, victim);
        vm.stopPrank();
        assertTrue(c.hasRole(role, victim));

        // a third party tries to renounce the victim's role
        vm.prank(attacker);
        bool ok;
        try c.renounceRole(role, victim) {
            ok = true;
        } catch {
            ok = false;
        }

        // rule: whether it reverts or not, the victim must still hold the role
        assertTrue(c.hasRole(role, victim), "victim lost role via foreign renounce");
    }
}
